    def __init__(self, repository, pricing):
        self._repository = repository            # required - set once, never reassigned
        self._pricing = pricing                   # required - same guarantee
        self._fraud_detection = None              # optional - may stay None

    def set_fraud_detection_service(self, fraud_detection):
        self._fraud_detection = fraud_detection   # called only by the customers who actually need it

    def place_order(self, order):
