class OrderService {
    private final OrderRepository repository;      // required - final, immutable, enforced at construction
    private final PricingEngine pricing;            // required - same guarantee
    private FraudDetectionService fraudDetection;    // optional - not final, may stay null

    OrderService(OrderRepository repository, PricingEngine pricing) {
