// FIXED - required dependencies via constructor, optional via setter

class Order {
public:
    Order(std::string id, double baseAmount) : id_(std::move(id)), baseAmount_(baseAmount) {}

    const std::string& getId() const { return id_; }
    double getBaseAmount() const { return baseAmount_; }

private:
    std::string id_;
    double baseAmount_;
};

class OrderRepository {
public:
    void save(const Order& order) {
        std::cout << "Order saved: " << order.getId() << std::endl;
    }
};

class PricingEngine {
public:
    double calculatePrice(const Order& order) {
        return order.getBaseAmount() * 1.0;
    }
};

class FraudDetectionService {
public:
    void screen(const Order& order) {
        std::cout << "Fraud check passed for order: " << order.getId() << std::endl;
    }
};

class OrderService {
public:
    OrderService(OrderRepository& repository, PricingEngine& pricing)
        : repository_(repository), pricing_(pricing), fraudDetection_(nullptr) {}   // old callers compile and run unchanged

    void setFraudDetectionService(FraudDetectionService& fraudDetection) {
        fraudDetection_ = &fraudDetection;   // called only by the customers who actually need it
    }

    void placeOrder(const Order& order) {
        double finalPrice = pricing_.calculatePrice(order);
        std::cout << "Calculated price: " << finalPrice << std::endl;

        if (fraudDetection_ != nullptr) {    // must check, because it's genuinely optional
            fraudDetection_->screen(order);
        } else {
            std::cout << "No fraud detection configured for this order" << std::endl;
        }

        repository_.save(order);
    }

private:
    OrderRepository& repository_;             // required - reference, immutable, enforced at construction
    PricingEngine& pricing_;                  // required - same guarantee
    FraudDetectionService* fraudDetection_;    // optional - pointer, may stay nullptr
};

int main() {
    OrderRepository repository;
    PricingEngine pricing;
    FraudDetectionService fraud;

    Order order1("ORD-1", 100.0);
    OrderService basicService(repository, pricing);
    basicService.placeOrder(order1);

    std::cout << "---" << std::endl;

    Order order2("ORD-2", 250.0);
    OrderService enterpriseService(repository, pricing);
    enterpriseService.setFraudDetectionService(fraud);
    enterpriseService.placeOrder(order2);

    return 0;
}
